    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate integers p, q, r so that a = 3p + 2q - 2r is a positive integer
# and feasibility/non-degeneracy constraints hold.
# Constraints ensured:
# 1) r <= p + q (feasibility of local patterns)
# 2) w = 2p + q - 2r >= 1 (nontrivial 'exactly one' count in a remaining class)
# 3) a in a moderate range for contest flavor (e.g., 20 <= a <= 150)
# 4) p != q to avoid trivial symmetry
for _ in range(10000):
    p = rng.randint(6, 60)
    q = rng.randint(6, 60)
    r = rng.randint(6, 70)
    # Basic feasibility
    if r > p + q:
        continue
    a = 3*p + 2*q - 2*r
    if a < 20 or a > 150:
        continue
    w = 2*p + q - 2*r
    if w <= 0:
        continue
    # Feasible A-range for nonnegative 3-bit pattern decomposition
    lo = max(0, r - p)
    hi = min(r, q)
    if lo > hi:
        continue
    if p == q:
        continue
    # Additional nontriviality: avoid r equal to p or q
    if r == p or r == q:
        continue
    return {'p': p, 'q': q, 'r': r}
# Fallback deterministic instance (checked to satisfy constraints):
p, q, r = 14, 19, 17  # a = 3*14 + 2*19 - 2*17 = 42 + 38 - 34 = 46; w = 28 + 19 - 34 = 13 > 0
return {'p': p, 'q': q, 'r': r}

